<?php declare(strict_types=1); ?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rezervasyon yönetimi</title><style>
*{box-sizing:border-box}body{font-family:system-ui;background:#f4f7f4;color:#26332b;margin:0}.wrap{max-width:1180px;margin:30px auto;padding:0 16px}.head{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.muted{color:#718077;font-size:13px}.filters{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.filters a{padding:9px 13px;border:1px solid #dfe8e1;border-radius:20px;text-decoration:none;color:#365746;background:#fff;font-size:13px}.filters a.active{background:#176b50;color:#fff;border-color:#176b50}.item{background:#fff;border:1px solid #e4ebe5;border-radius:15px;padding:17px;margin:11px 0;display:grid;grid-template-columns:minmax(0,2fr) minmax(150px,1fr) minmax(130px,1fr) minmax(180px,1fr);gap:14px;align-items:center}.tag{display:inline-block;background:#edf5ef;padding:5px 9px;border-radius:20px;font-size:12px}.actions{display:flex;gap:7px;flex-wrap:wrap}.actions select,.actions button{padding:9px;border:1px solid #dfe6e0;border-radius:8px;font:inherit}.actions button{background:#176b50;color:#fff;font-weight:750;border:0}.empty{background:#fff;padding:28px;border-radius:14px;text-align:center}.manual{background:#fff;border:1px solid #e4ebe5;border-radius:15px;padding:18px;margin:18px 0}.manual h2{font-size:18px;margin:0 0 12px}.manual-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.manual label{font-size:12px;font-weight:700;color:#536258}.manual input,.manual select{box-sizing:border-box;width:100%;min-height:42px;padding:9px;border:1px solid #dfe6e0;border-radius:8px;font:inherit;margin-top:5px}.manual button{margin-top:14px;padding:11px 16px;border:0;border-radius:8px;background:#176b50;color:#fff;font-weight:750}@media(max-width:800px){.manual-grid{grid-template-columns:1fr 1fr}}@media(max-width:480px){.manual-grid{grid-template-columns:1fr}}.booking-title{font-weight:800}.price{font-weight:850;white-space:nowrap}@media(max-width:800px){.item{grid-template-columns:1fr;gap:10px;padding:15px}.actions{grid-column:auto}.actions form{width:100%;display:grid;grid-template-columns:1fr;gap:9px}.actions select,.actions button{width:100%;min-height:44px}.head{align-items:flex-start}.wrap{margin:20px auto}}
</style></head><body><main class="wrap"><div class="head"><div><h1>Rezervasyon yönetimi</h1><p class="muted">Talepleri filtreleyin, ayrıntıları inceleyin ve durumları yönetin.</p></div><a href="<?= e(app_url('/admin')) ?>">← Yönetim paneli</a></div><section class="manual"><h2>Telefonla / dış kanaldan manuel rezervasyon ekle</h2><form method="post" action="<?= e(app_url('/admin/bookings/manual')) ?>"><?= csrf_field() ?><div class="manual-grid"><label>Villa<select name="property_id" required><option value="">Villa seçin</option><?php foreach(($bookingProperties??[]) as $bp): ?><option value="<?= (int)$bp['id'] ?>" data-early="<?= (int)($bp['early_checkin_enabled']??0) ?>" data-early-fee="<?= e((string)($bp['early_checkin_fee']??0)) ?>" data-late="<?= (int)($bp['late_checkout_enabled']??0) ?>" data-late-fee="<?= e((string)($bp['late_checkout_fee']??0)) ?>"><?= e($bp['title']) ?> · en fazla <?= (int)$bp['max_guests'] ?> kişi</option><?php endforeach; ?></select></label><label>Misafir adı soyadı<input name="guest_name" maxlength="190" required></label><label>E-posta (isteğe bağlı)<input type="email" name="guest_email" maxlength="190"></label><label>Telefon (isteğe bağlı)<input name="guest_phone" maxlength="40"></label><label>Rezervasyon kanalı<select name="booking_source"><option value="phone">Telefon</option><option value="whatsapp">WhatsApp</option><option value="agency">Acente</option><option value="walk_in">Yerinde</option><option value="other">Diğer</option></select></label><label>Giriş tarihi<input type="date" name="check_in" min="<?= e(date('Y-m-d')) ?>" required></label><label>Çıkış tarihi<input type="date" name="check_out" min="<?= e(date('Y-m-d',strtotime('+1 day'))) ?>" required></label><label>Misafir sayısı<input type="number" name="guests" min="1" value="2" required></label><label id="manualEarlyWrap" hidden>Ek hizmet<input type="checkbox" name="early_checkin" value="1" id="manualEarly"> Erken giriş talebi <span id="manualEarlyFee"></span></label><label id="manualLateWrap" hidden>Ek hizmet<input type="checkbox" name="late_checkout" value="1" id="manualLate"> Geç çıkış talebi <span id="manualLateFee"></span></label><label>Toplam tutar (boş: otomatik hesapla)<input type="number" name="total_amount" min="0" step=".01" placeholder="Otomatik fiyat"></label></div><button type="submit">Rezervasyonu kaydet ve tarihleri kapat</button><p class="muted">Kaydedilen manuel rezervasyon onaylı olarak takvimi anında kapatır. İptal edilirse tarihler yeniden müsait olur.</p></form></section>
<nav class="filters"><?php foreach([''=>'Tümü','pending'=>'Bekleyen','confirmed'=>'Onaylanan','cancelled'=>'İptal edilen','completed'=>'Tamamlanan'] as $key=>$label): ?><a class="<?= ($bookingFilter??'')===$key?'active':'' ?>" href="<?= e(app_url('/admin/bookings'.($key!==''?'?status='.rawurlencode($key):''))) ?>"><?= e($label) ?></a><?php endforeach; ?></nav>
<?php foreach($bookings as $b): ?><article class="item"><div><div class="booking-title"><?= e($b['title']) ?></div><div class="muted"><?= e($b['guest_name']) ?> · <?= e($b['guest_email']) ?><?= !empty($b['guest_phone'])?' · '.e($b['guest_phone']):'' ?></div><div class="muted"><?= e($b['booking_code']) ?> · <?= e(['website'=>'Web sitesi','phone'=>'Telefon','whatsapp'=>'WhatsApp','agency'=>'Acente','walk_in'=>'Yerinde','other'=>'Diğer','offline'=>'Manuel / dış kanal'][$b['booking_source']??'website']??'Diğer') ?></div><?php if(!empty($b['early_checkin_requested'])||!empty($b['late_checkout_requested'])): ?><div class="muted">Ek talepler: <?= !empty($b['early_checkin_requested'])?'Erken giriş ('.number_format((float)$b['early_checkin_fee'],2,',','.').' '.e($b['currency']).')':'' ?> <?= !empty($b['late_checkout_requested'])?'Geç çıkış ('.number_format((float)$b['late_checkout_fee'],2,',','.').' '.e($b['currency']).')':'' ?></div><?php endif; ?></div><div><?= e(date('d.m.Y',strtotime($b['check_in']))) ?> – <?= e(date('d.m.Y',strtotime($b['check_out']))) ?><div class="muted"><?= (int)$b['guests'] ?> misafir</div></div><div><div class="price"><?= e(number_format((float)$b['total'],2,',','.')) ?> <?= e($b['currency']) ?></div><span class="tag"><?= e(['pending'=>'Bekliyor','confirmed'=>'Onaylandı','cancelled'=>'İptal','completed'=>'Tamamlandı'][$b['status']]??$b['status']) ?></span></div><div class="actions"><form method="post" action="<?= e(app_url('/admin/bookings/status')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$b['id'] ?>"><select name="status"><option value="pending" <?= $b['status']==='pending'?'selected':'' ?>>Bekliyor</option><option value="confirmed" <?= $b['status']==='confirmed'?'selected':'' ?>>Onayla</option><option value="cancelled" <?= $b['status']==='cancelled'?'selected':'' ?>>İptal et</option><option value="completed" <?= $b['status']==='completed'?'selected':'' ?>>Tamamlandı</option></select><button type="submit">Kaydet</button></form></div></article><?php endforeach; ?><?php if(!$bookings): ?><div class="empty">Bu filtrede rezervasyon bulunmuyor.</div><?php endif; ?><script>(function(){var property=document.querySelector('.manual select[name="property_id"]'),earlyWrap=document.getElementById('manualEarlyWrap'),lateWrap=document.getElementById('manualLateWrap'),early=document.getElementById('manualEarly'),late=document.getElementById('manualLate');if(!property)return;function sync(){var o=property.options[property.selectedIndex];var e=o&&o.dataset.early==='1',l=o&&o.dataset.late==='1';earlyWrap.hidden=!e;lateWrap.hidden=!l;if(!e)early.checked=false;if(!l)late.checked=false;document.getElementById('manualEarlyFee').textContent=e?' · '+o.dataset.earlyFee+' ek ücret':'';document.getElementById('manualLateFee').textContent=l?' · '+o.dataset.lateFee+' ek ücret':''}property.addEventListener('change',sync);sync()})();</script></main></body></html>